class DecodeError(Exception):
    def __init__(self, kind, position):
        super().__init__(f"{kind} at {position}")
        self.kind = kind
        self.position = position


class BitWriter:
    def __init__(self):
        self.data = bytearray()
        self.partial = 0
        self.used = 0
        self.bit_count = 0

    def write(self, value, width):
        for shift in range(width - 1, -1, -1):
            self.partial = (self.partial << 1) | ((value >> shift) & 1)
            self.used += 1
            if self.used == 8:
                self.data.append(self.partial)
                self.partial = 0
                self.used = 0
        self.bit_count += width

    def finish(self):
        if self.used:
            return bytes(self.data) + bytes((self.partial << (8 - self.used),))
        return bytes(self.data)


class BitReader:
    def __init__(self, payload, zero_fill=False):
        self.payload = payload
        self.position = 0
        self.limit = len(payload) * 8
        self.zero_fill = zero_fill

    def read(self, width, output_position=0):
        if not self.zero_fill and self.position + width > self.limit:
            raise DecodeError("end_of_data", output_position)
        value = 0
        for _ in range(width):
            value <<= 1
            if self.position < self.limit:
                byte = self.payload[self.position // 8]
                value |= (byte >> (7 - self.position % 8)) & 1
            self.position += 1
        return value

from collections import defaultdict, deque

from bitio import DecodeError


def tokenize(data, offset_bits, length_bits):
    window = 1 << offset_bits
    lookahead = (1 << length_bits) + 2
    prefixes = defaultdict(deque)
    tokens = []
    position = 0
    while position < len(data):
        distance = 0
        longest = 0
        limit = min(lookahead, len(data) - position)
        if limit >= 3:
            candidates = prefixes[data[position:position + 3]]
            while candidates and candidates[0] < position - window:
                candidates.popleft()
            for start in reversed(candidates):
                candidate_distance = position - start
                length = 3
                while (length < limit and
                       data[position + length] ==
                       data[position + length - candidate_distance]):
                    length += 1
                if length > longest:
                    distance = candidate_distance
                    longest = length
                if longest == limit:
                    break
        if longest >= 3:
            tokens.append((distance, longest))
            consumed = longest
        else:
            tokens.append(data[position])
            consumed = 1
        for start in range(position, min(position + consumed, len(data) - 2)):
            prefixes[data[start:start + 3]].append(start)
        position += consumed
    return tokens


def copy_match(output, distance, length, original_size):
    if distance > len(output):
        raise DecodeError("bad_offset", len(output))
    if len(output) + length > original_size:
        raise DecodeError("overrun", len(output))
    for _ in range(length):
        output.append(output[-distance])
